package br.com.marquesautodetail.api.agendamento; import br.com.marquesautodetail.api.agendamento.dto.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/agendamentos") public class AgendamentoController{ private final AgendamentoService service; public AgendamentoController(AgendamentoService service){this.service=service;} @PostMapping public AgendamentoResponse criar(@RequestBody AgendamentoRequest r){return service.criar(r);} @GetMapping("/me") public List<AgendamentoResponse> meus(){return service.meus();} @GetMapping public List<AgendamentoResponse> meusLegado(){return service.meus();} @PutMapping("/{id}/confirmar") public AgendamentoResponse confirmar(@PathVariable Long id){return service.status(id,StatusAgendamento.CONFIRMADO);} @PutMapping("/{id}/recusar") public AgendamentoResponse recusar(@PathVariable Long id){return service.status(id,StatusAgendamento.RECUSADO);} @PutMapping("/{id}/cancelar") public AgendamentoResponse cancelar(@PathVariable Long id){return service.status(id,StatusAgendamento.CANCELADO);} @PutMapping("/{id}/concluir") public AgendamentoResponse concluir(@PathVariable Long id){return service.status(id,StatusAgendamento.CONCLUIDO);} }
